  assert(byLetterFontFamily.length > 0 && byLetterFontFamily.every(run => run.fontFamily.toLowerCase().includes('georgia')), `A p:set style.fontFamily must apply to the text frame: ${JSON.stringify(byLetterFontFamily)}`)
