      connected: video?.isConnected,
      paused: video?.paused,
      currentTime: video?.currentTime,
      controls: video?.controls,
      layerAboveSlide: Number(getComputedStyle(layer).zIndex) > Number(getComputedStyle(slide).zIndex),
